function rm(k,vars={}){let s=ramadanCopy[k]?.[exIndex()]||k;for(const [key,value]of Object.entries(vars))s=s.replaceAll('{'+key+'}',String(value));return s}
function shamsLogo(extra=''){return `<span class="shams-mark ${extra}" role="img" aria-label="Shams"></span>`}
function personalMessage(k){const name=personalProfile().name;return name?`<p class="personal-message" data-localized="true">${esc(rm(k,{name}))}</p>`:''}
uiMap.set('Ramazan',ramadanCopy.ramadan);experienceCopy.pearl=ramadanCopy.pearl;experienceCopy.sand=ramadanCopy.sand;
themeOptions.push({id:'pearl',bg:'#F3F0FF',end:'#E8E2F8',button:'#6654B8',accent:'#8D6110'},{id:'sand',bg:'#F7EFE3',end:'#EDE0CD',button:'#8A5439',accent:'#8A6511'});
const ramadanSeasons=new Map();let ramadanCalendarOpen=false,ramadanYear=null,ramadanTimeStamp='',ramadanTimeData=null,ramadanTimeError=false,ramadanTimeCached=false,ramadanRequest=0;
function hijriParts(d){const p=new Intl.DateTimeFormat('en-u-ca-islamic-umalqura',{year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'}).formatToParts(new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate(),12)));const get=k=>Number(p.find(x=>x.type===k)?.value);return {year:get('year'),month:get('month'),day:get('day')}}
function upcomingRamadanYear(d=placeToday()){const h=hijriParts(d);return h.year+(h.month>9?1:0)}
function ramadanSeason(year){if(ramadanSeasons.has(year))return ramadanSeasons.get(year);const guess=new Date(0);guess.setUTCFullYear(622,6,19);guess.setUTCDate(guess.getUTCDate()+Math.floor((year-1)*354.367)-70);const dates=[];for(let i=0;i<500;i++){const d=new Date(guess);d.setUTCDate(d.getUTCDate()+i);const local=new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),12),h=hijriParts(local);if(h.year===year&&h.month===9)dates.push(key(local));else if(dates.length)break}if(dates.length<29||dates.length>30)throw Error('Ramadan calendar unavailable');const result={year,dates,start:dates[0],end:dates.at(-1)};ramadanSeasons.set(year,result);return result}
function dateFromKey(k){const [y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d,12)}
function setRamadanYear(value){ramadanYear=Number(value);render()}
function toggleRamadanDay(k){const season=ramadanSeason(ramadanYear||upcomingRamadanYear());if(!season.dates.includes(k))return;if(k>key(placeToday()))return toast(rm('future'));fasts[k]=!fasts[k];save('nur-fasts',fasts);render()}
function zoneParts(now,tz){const p=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now),get=k=>Number(p.find(x=>x.type===k)?.value);return {year:get('year'),month:get('month'),day:get('day'),hour:get('hour'),minute:get('minute'),second:get('second')}}
function zonedInstant(ymd,clock,tz){if(!/^\d{2}:\d{2}$/.test(clock||''))return NaN;const [y,m,d]=ymd.split('-').map(Number),[h,min]=clock.split(':').map(Number),target=Date.UTC(y,m-1,d,h,min);let time=target;for(let i=0;i<3;i++){const p=zoneParts(new Date(time),tz),shown=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second);time+=target-shown}return time}
function ramadanTimeKey(){const p=place(),c=read('basira-calculation',{method:13,school:0});return JSON.stringify([key(placeToday()),p.latitude,p.longitude,p.timezone,c.method,c.school])}
async function ensureRamadanTimes(force=false){const stamp=ramadanTimeKey();if(!force&&stamp===ramadanTimeStamp)return;ramadanTimeStamp=stamp;const request=++ramadanRequest;ramadanTimeData=null;ramadanTimeError=false;ramadanTimeCached=false;const cache=read('shams-ramadan-times',{});if(cache.stamp===stamp){ramadanTimeData=cache.data;ramadanTimeCached=true}const p=place(),c=read('basira-calculation',{method:13,school:0}),today=key(placeToday()),next=dateFromKey(today);next.setDate(next.getDate()+1);const tomorrow=key(next),params=new URLSearchParams({latitude:String(p.latitude),longitude:String(p.longitude),method:String(c.method??13),school:String(c.school??0)});if(p.timezone)params.set('timezonestring',p.timezone);
try{const results=await Promise.all([today,tomorrow].map(async k=>{const [y,m,d]=k.split('-'),res=await fetch(`https://api.aladhan.com/v1/timings/${d}-${m}-${y}?${params}`,{signal:AbortSignal.timeout(15000)}),j=await res.json();if(!res.ok||j.code!==200)throw Error();const fajr=j.data.timings.Fajr?.slice(0,5),maghrib=j.data.timings.Maghrib?.slice(0,5);if(![fajr,maghrib].every(t=>/^\d{2}:\d{2}$/.test(t)))throw Error();return {date:k,fajr,maghrib,timezone:j.data.meta.timezone,method:j.data.meta.method?.name||'AlAdhan'}}));if(request!==ramadanRequest||stamp!==ramadanTimeKey())return;ramadanTimeData={today:results[0],tomorrow:results[1]};ramadanTimeCached=false;save('shams-ramadan-times',{stamp,data:ramadanTimeData})}catch{if(request!==ramadanRequest)return;ramadanTimeError=true}if(route==='ramadan')render()}
function fastingCountdown(data,now=Date.now()){if(!data)return null;const t=data.today,tz=t.timezone||place().timezone,fajr=zonedInstant(t.date,t.fajr,tz),iftar=zonedInstant(t.date,t.maghrib,tz);if(![fajr,iftar].every(Number.isFinite)||iftar<=fajr)return null;let target=iftar,start=fajr,label='untilIftar';if(now<fajr){target=fajr;start=zonedInstant(t.date,'00:00',tz);label='untilSahur'}else if(now>=iftar){target=zonedInstant(data.tomorrow.date,data.tomorrow.fajr,tz);start=iftar;label='nextSahur'}if(!Number.isFinite(target)||target<=now)return null;return {seconds:Math.max(0,Math.ceil((target-now)/1000)),progress:Math.min(1,Math.max(0,(now-start)/(target-start))),label,target}}
function updateRamadanClock(){if(route!=='ramadan')return;if(ramadanTimeStamp!==ramadanTimeKey()){ensureRamadanTimes();return}const state=fastingCountdown(ramadanTimeData),time=document.querySelector('#ramadanCountdown'),label=document.querySelector('#ramadanCountdownLabel'),ring=document.querySelector('#ramadanRing'),percent=document.querySelector('#ramadanPercent');if(!time)return;if(!state){time.textContent='— : — : —';if(label)label.textContent=ramadanTimeError?rm('unavailable'):tr('Yüklənir…');return}time.textContent=[Math.floor(state.seconds/3600),Math.floor(state.seconds%3600/60),state.seconds%60].map(x=>String(x).padStart(2,'0')).join(':');label.textContent=rm(state.label);ring?.style.setProperty('--ring-progress',Math.round(state.progress*100)+'%');if(percent)percent.textContent=Math.round(state.progress*100)+'%'}
function ramadanDua(){return `<details class="ramadan-dua card" open><summary><span>✦ ${rm('iftarDua')}</span><span>⌄</span></summary><p class="arabic" lang="ar" dir="rtl">ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ</p><p>${rm('duaMeaning')}</p><a href="https://sunnah.com/abudawud:2357" target="_blank" rel="noopener">Abu Dawud 2357 ↗</a></details>`}
function ramadanPage(){ensureRamadanTimes();const today=key(placeToday()),current=upcomingRamadanYear(),season=ramadanSeason(ramadanYear||current);ramadanYear=season.year;const count=season.dates.filter(k=>fasts[k]).length,dayNumber=season.dates.indexOf(today)+1,status=today<season.start?rm('next'):today>season.end?rm('ended'):rm('today')+' · '+dayNumber,t=ramadanTimeData?.today;
const html=head(rm('ramadan'),'')+personalMessage('ramadanHello')+ramadanDua()+`<section class="card ramadan-clock"><div class="ramadan-clock-head"><div><h2>☾ ${rm('ramadan')}</h2><p>${status}</p><small>${localizedDate(placeToday())}</small></div><div id="ramadanRing" class="ramadan-ring" style="--ring-progress:0%" aria-hidden="true"><div><span id="ramadanPercent">—</span></div></div></div><div class="ramadan-countdown"><span id="ramadanCountdownLabel">${tr('Yüklənir…')}</span><strong id="ramadanCountdown" dir="ltr">— : — : —</strong></div><div class="ramadan-hours"><div><span>☀ ${rm('sahur')}</span><strong>${t?.fajr||'—:—'}</strong></div><div><span>☀ ${rm('iftar')}</span><strong>${t?.maghrib||'—:—'}</strong></div></div><button class="ramadan-location" onclick="go('locations')">⌖ ${esc(placeLabel())} · ${esc(t?.timezone||place().timezone)} ›</button>${ramadanTimeCached?`<p class="notice">${rm('cached')}</p>`:''}${ramadanTimeError?`<button class="textbtn" onclick="ensureRamadanTimes(true)">${rm('retry')} ↻</button>`:''}</section><section class="card ramadan-journal"><div class="ramadan-journal-head"><div><small>${rm('fasted')}</small><strong>${count}<span> / ${season.dates.length}</span></strong></div><label>${rm('season')}<select onchange="setRamadanYear(this.value)" aria-label="${rm('season')}">${Array.from({length:4},(_,i)=>current-2+i).map(y=>`<option value="${y}" ${y===season.year?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="ramadan-month-dates">${localizedDate(dateFromKey(season.start))} — ${localizedDate(dateFromKey(season.end))}</div><details class="ramadan-calendar" ${ramadanCalendarOpen?'open':''} ontoggle="if(this.isConnected)ramadanCalendarOpen=this.open"><summary>${rm('recordDays')} <span>⌄</span></summary><p>${rm('mark')}</p><div class="ramadan-days">${season.dates.map((k,i)=>`<button aria-label="${i+1} · ${localizedDate(dateFromKey(k))} · ${fasts[k]?rm('recorded'):rm('notRecorded')}" aria-pressed="${!!fasts[k]}" ${k>today?'disabled':''} class="${fasts[k]?'fasted':''} ${k===today?'today':''}" onclick="toggleRamadanDay('${k}')"><span>${i+1}</span><i>${fasts[k]?'✓':'·'}</i></button>`).join('')}</div></details><p class="notice">${rm('moonNote')}</p><p class="notice">${rm('methodNote')} · ${esc(t?.method||'AlAdhan')}</p></section>`;setTimeout(updateRamadanClock,0);return html}
function initializeShams(){setInterval(updateRamadanClock,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateRamadanClock()})}
function humanPosture(p,title=''){const school=guideState().school;let cell=school==='hanafi'?0:1,caption='Dik dayanın';if(title==='Hazırlıq və niyyət'||title==='Rükudan doğrulun')cell=1;if(p==='takbir'){cell=2;caption='Əlləri qaldırın'}else if(p==='qunut'){cell=3;caption='Ovuclar yuxarı'}else if(p==='bow'){cell=4;caption='Beli əyib əlləri dizlərə qoyun'}else if(p==='prostrate'){cell=5;caption='Alın, əllər, dizlər və ayaq barmaqları yerdə'}else if(p==='sit'){cell=title==='Salam və tamamlanma'?7:6;caption='Dizlər üstə sakit oturun'}return `<figure class="human-posture" data-school="${school}"><div class="posture-photo" role="img" aria-label="${tr(caption)}" style="--pose-x:${cell===5?34.3:(cell%4)*100/3}%;--pose-y:${Math.floor(cell/4)*100}%"></div><figcaption><span>${tr(caption)}</span>${p==='prostrate'&&school==='jafari'?`<small>${rm('turbah')}</small>`:''}</figcaption></figure>`}
